mapper.select:
SELECT DEPT_CD AS deptCd, DEPT_LVL AS deptLvl
FROM hrm_dept_master
WHERE UPPER_DEPT_CD = #{upperDeptCd}

mapper.update:
UPDATE hrm_dept_master
DEPT_NM = #{deptNm}, DEPT_ENG_NM = #{deptEngNm}, DEPT_SHRT_NM = #{deptShrtNm}, DEPT_SE_CD = #{deptSeCd}, UPPER_DEPT_CD = #{upperDeptCd}, DEPT_LVL = #{deptLvl}, DEPT_ORDR = #{deptOrdr}, DEPT_MNGR_NO = #{deptMngrNo}, DEPT_TELNO = #{deptTelno}, DEPT_LCTN_NM = #{deptLctnNm}, ESTBL_YMD = #{estblYmd}, USE_YN = #{useYn}
WHERE DEPT_CD = #{deptCd}

UPDATE hrm_dept_master
SET DEPT_LVL = #{deptLvl}
WHERE DEPT_CD = #{deptCd}
